use strict;
use POSIX qw(ceil);

my $s=<>;
$s =~ /(\d+)\/(\d+)/;
my($p,$q)=reduce($1,$2);

my @s;

for(my $k=1;;$k++) {
    last if($k*$p<=$q);
    push(@s,$k);
    # subtract 1/k from p/q
    ($p,$q)=reduce($p*$k-$q,$q*$k);
}

push(@s,fibo($p,$q));
print join(" + ",map{"1/$_"} @s)."\n";

sub fibo {
    my($p,$q)=reduce(@_);
    return($q) if($p==1);
    my $r = POSIX::ceil($q/$p);
    return($r, fibo((((-$q)%$p)+$p)%$p,$q*$r));
}

sub reduce {
    my($p,$q)=@_;
    my($g)=gcd($p,$q);
    return($p/$g,$q/$g) if($g>1);
    return($p,$q);
}

sub gcd {
    my ($a, $b) = @_;
    return 0 == $b ? $a : gcd($b, $a % $b);
}
